-- Rehearsal body for migration 0191 (statement-evidence link / unlink, .eml storage). Runs inside ONE transaction that rehearse_finance_stamp.sh ROLLS BACK. Local scratch database only. Synthetic users/entities.
-- Every check raises an exception on failure; the script stops at the first one (ON_ERROR_STOP).
set session_replication_role = replica;
insert into auth.users (id, email) select ('00000000-0000-4000-8000-0000000000'||lpad(to_hex(n),2,'0'))::uuid, 'f'||n||'@e2e.test' from generate_series(240,243) n on conflict do nothing;
insert into public.profiles (id, full_name, access_status) select ('00000000-0000-4000-8000-0000000000'||lpad(to_hex(n),2,'0'))::uuid, 'Fin '||n, 'active' from generate_series(240,243) n on conflict do nothing;
insert into public.user_roles (user_id, role_id) select '00000000-0000-4000-8000-0000000000f0', r.id from public.roles r where r.slug = 'super_admin' on conflict do nothing;      -- f0 = 240: Super Admin
insert into public.user_roles (user_id, role_id) select '00000000-0000-4000-8000-0000000000f1', r.id from public.roles r where r.slug = 'admin' on conflict do nothing;            -- f1 = 241: ordinary admin
insert into public.employing_entities (id, name, slug, legal_name, verification_status) values
  ('11111111-1111-4111-8111-111111111101', 'Fin Entity A', 'fin-a', 'FIN ENTITY A W.L.L.', 'verified'), ('11111111-1111-4111-8111-111111111102', 'Fin Entity B', 'fin-b', 'FIN ENTITY B W.L.L.', 'verified') on conflict do nothing;
insert into public.employing_entity_documents (id, employing_entity_id, document_type, storage_path, uploaded_by, file_sha256, original_filename, mime_type, size_bytes) values
  ('22222222-2222-4222-8222-222222222201', '11111111-1111-4111-8111-111111111101', 'purchase_receipt', 'a/inv.jpg', '00000000-0000-4000-8000-0000000000f0', repeat('a', 64), 'invoice.jpg', 'image/jpeg', 1000),
  ('22222222-2222-4222-8222-222222222202', '11111111-1111-4111-8111-111111111101', 'other_financial_document', 'a/pl.pdf', '00000000-0000-4000-8000-0000000000f0', repeat('b', 64), 'receipt_SQ1.pdf', 'application/pdf', 2000),
  ('22222222-2222-4222-8222-222222222203', '11111111-1111-4111-8111-111111111102', 'other_financial_document', 'b/pl.pdf', '00000000-0000-4000-8000-0000000000f0', repeat('c', 64), 'other_entity.pdf', 'application/pdf', 2000),
  ('22222222-2222-4222-8222-222222222204', '11111111-1111-4111-8111-111111111101', 'other_financial_document', 'a/bank.pdf', '00000000-0000-4000-8000-0000000000f0', repeat('d', 64), 'statement.pdf', 'application/pdf', 3000)
  on conflict do nothing;
set session_replication_role = origin;
insert into public.employing_entity_documents (id, employing_entity_id, document_type, storage_path, uploaded_by, file_sha256, original_filename, mime_type, size_bytes) values
  ('22222222-2222-4222-8222-222222222205', '11111111-1111-4111-8111-111111111102', 'purchase_receipt', 'b/inv.jpg', '00000000-0000-4000-8000-0000000000f0', repeat('e', 64), 'ghana-invoice.jpg', 'image/jpeg', 1000) on conflict do nothing;
-- the Founder identity (lab only, inside the rolled-back transaction): the synthetic Super Admin f0 is the ACTIVE Founder
set session_replication_role = replica; delete from public.founder_identities;
insert into public.founder_identities (profile_id, status, designation_reference) values ('00000000-0000-4000-8000-0000000000f0', 'active', 'Rehearsal Founder designation reference (synthetic)'); set session_replication_role = origin;
create or replace function pg_temp.err(q text) returns text language plpgsql as $$ begin execute q; return ''; exception when others then return sqlerrm; end $$;
create or replace function pg_temp.must(cond boolean, msg text) returns void language plpgsql as $$ begin if not coalesce(cond, false) then raise exception 'REHEARSAL FAILED: %', msg; end if; end $$;
create temp table t_ids (name text primary key, id uuid); grant all on t_ids to public;
create or replace function pg_temp.mk(inv text, fund text, ent uuid default '11111111-1111-4111-8111-111111111101') returns uuid language plpgsql as $$
declare r record;
begin select * into r from public.record_equipment_acquisition(jsonb_build_object('entityId', ent, 'acquisition', jsonb_build_object('supplier','Synthetic Supplier','invoiceNumber',inv,'purchaseDate','2026-11-01','itemDescription','Synthetic pen display','quantity',1,'currency','QAR','listPrice',1149,'discount',0,'net',1149,
  'invoiceDocumentId', case when ent = '11111111-1111-4111-8111-111111111101' then '22222222-2222-4222-8222-222222222201' else '22222222-2222-4222-8222-222222222205' end,'fundingStatus',fund,'fundingNote','Founder statement: company card')), '00000000-0000-4000-8000-0000000000f0'); return r.acquisition_id; end $$;

-- ---------------------------------------------------------------- setup (synthetic only)
set session_replication_role = replica;
insert into public.employing_entity_documents (id, employing_entity_id, document_type, storage_path, uploaded_by, file_sha256, original_filename, mime_type, size_bytes) values
  ('22222222-2222-4222-8222-222222222206', '11111111-1111-4111-8111-111111111101', 'other_financial_document', 'a/provider.eml', '00000000-0000-4000-8000-0000000000f0', repeat('6', 64), 'provider.eml', 'message/rfc822', 3000),
  ('22222222-2222-4222-8222-222222222207', '11111111-1111-4111-8111-111111111101', 'other_financial_document', 'a/statement2.jpg', '00000000-0000-4000-8000-0000000000f0', repeat('7', 64), 'statement2.jpg', 'image/jpeg', 4000)
  on conflict do nothing;
set session_replication_role = origin;
create or replace function pg_temp.fin(inv text, ref text, paid boolean default true, ent uuid default '11111111-1111-4111-8111-111111111101') returns uuid language plpgsql as $$
declare r record;
begin select * into r from public.record_equipment_acquisition(jsonb_build_object('entityId', ent, 'acquisition', jsonb_build_object('supplier','Synthetic Supplier','invoiceNumber',inv,'purchaseDate','2026-11-01','itemDescription','Synthetic pen display','quantity',1,'currency','QAR','listPrice',1149,'discount',0,'net',1149,
  'invoiceDocumentId','22222222-2222-4222-8222-222222222201','fundingStatus','company_account','fundingNote','Founder statement: company card'),
  'financing', jsonb_build_object('provider','SynthPay','reference',ref,'merchant','Synthetic Supplier','count',4,'plannedOn','2026-11-01','confirmationDocumentId','22222222-2222-4222-8222-222222222202','scheduleBasis','founder_expected_months',
    'instalments', jsonb_build_array(jsonb_build_object('sequence',1,'amount',287.25,'expectedMonth','2026-11-01'),jsonb_build_object('sequence',2,'amount',287.25,'expectedMonth','2026-12-01'),jsonb_build_object('sequence',3,'amount',287.25,'expectedMonth','2027-01-01'),jsonb_build_object('sequence',4,'amount',287.25,'expectedMonth','2027-02-01')))
  ) || case when paid then jsonb_build_object('firstInstalmentPaid', jsonb_build_object('sequence',1,'paidOn',(current_date - 1)::text,'evidenceNote','Synthetic confirmation: down payment shown as paid')) else '{}'::jsonb end, '00000000-0000-4000-8000-0000000000f0'); return r.acquisition_id; end $$;

create or replace function pg_temp.lk(kind text, target uuid, doc uuid, ev jsonb, actor uuid default '00000000-0000-4000-8000-0000000000f0') returns text language plpgsql as $$
begin perform public.link_statement_evidence(kind, target, doc, ev, actor); return ''; exception when others then return sqlerrm; end $$;
create or replace function pg_temp.ul(kind text, target uuid, reason text, actor uuid default '00000000-0000-4000-8000-0000000000f0') returns text language plpgsql as $$
begin perform public.unlink_statement_evidence(kind, target, reason, actor); return ''; exception when others then return sqlerrm; end $$;
create or replace function pg_temp.vd(acq uuid, reason text default 'Entered with a wrong value; voided to record a correction') returns text language plpgsql as $$
begin perform public.void_equipment_acquisition(acq, reason, '00000000-0000-4000-8000-0000000000f0'); return ''; exception when others then return sqlerrm; end $$;
-- a statement-evidence payload that is valid for the first instalment of pg_temp.fin() (paid yesterday, 287.25 QAR); every refusal below changes exactly ONE field
create or replace function pg_temp.ev(over jsonb default '{}') returns jsonb language sql as $$
  select jsonb_build_object('holderKind','company','instrumentKind','credit_card','accountHolderAsPrinted','FIN ENTITY A W.L.L.','cardholderAsPrinted','Synthetic Cardholder','instrumentIdentityAsPrinted','card ending 4242',
    'periodFrom',(current_date - 20)::text,'periodTo',(current_date - 1)::text,'lineDate',(current_date - 1)::text,'lineAmount',287.25,'lineCurrency','QAR','lineDescriptionAsPrinted','SYNTHPAY ONLINE','page','2','paymentReference',null,
    'basisNote','Synthetic statement line matched to the reported first instalment') || over $$;
create or replace function pg_temp.ins1(acq uuid) returns uuid language sql as $$ select i.id from public.entity_financing_instalments i join public.entity_financing_obligations o on o.id = i.obligation_id where o.acquisition_id = acq and i.sequence = 1 $$;
create or replace function pg_temp.nev(t text) returns bigint language sql as $$ select count(*) from public.entity_finance_events where event_type = t $$;
create or replace function pg_temp.i(n text) returns uuid language sql as $$ select id from t_ids where name = n $$;
insert into t_ids values ('f1', pg_temp.fin('STM-1', 'SP-0001')), ('f2', pg_temp.fin('STM-2', 'SP-0002', false)), ('f3', pg_temp.fin('STM-3', 'SP-0003'));
create temp table t_b as select (select md5(coalesce(string_agg(row_to_json(a)::text, '|' order by a.id), '')) from public.company_assets a) assets_h, (select md5(coalesce(string_agg(row_to_json(x)::text, '|' order by x.id), '')) from public.asset_assignments x) assign_h,
  (select md5(string_agg(row_to_json(d)::text, '|' order by d.id)) from public.employing_entity_documents d) vault_h, (select count(*) from public.entity_expenses) exp_n, (select count(*) from public.payments) pay_n, (select count(*) from public.entity_acquisition_payments) apay_n,
  (select md5(string_agg(indexdef, '|' order by indexname)) from pg_indexes where tablename in ('entity_equipment_acquisitions','entity_financing_obligations','entity_financing_instalments')) idx_h,
  (select md5(string_agg(conrelid::regclass::text || conname || pg_get_constraintdef(oid), '|' order by conrelid::regclass::text, conname)) from pg_constraint where conrelid in ('public.entity_equipment_acquisitions'::regclass,'public.entity_financing_obligations'::regclass,'public.entity_financing_instalments'::regclass)) con_h,
  (select md5(string_agg(c.relname || a.privilege_type || a.grantee, '|' order by c.relname, a.privilege_type, a.grantee)) from pg_class c join pg_namespace n on n.oid = c.relnamespace, lateral (select (aclexplode(c.relacl)).privilege_type as privilege_type, (aclexplode(c.relacl)).grantee::regrole::text as grantee) a where n.nspname = 'public' and c.relname in ('entity_equipment_acquisitions','entity_financing_obligations','entity_financing_instalments','entity_finance_events')) grants_h,
  (select md5(string_agg(row_to_json(o)::text, '|' order by o.id)) from public.entity_financing_obligations o) obl_h;
grant all on t_b to public;
create temp table t_rows as select i.id, md5((to_jsonb(i) - 'bank_evidence_document_id')::text) h from public.entity_financing_instalments i; grant all on t_rows to public;

-- ---------------------------------------------------------------- 1. surface: privileges, bucket, event list
select pg_temp.must(has_function_privilege('service_role', 'public.link_statement_evidence(text, uuid, uuid, jsonb, uuid)', 'execute') and has_function_privilege('service_role', 'public.unlink_statement_evidence(text, uuid, text, uuid)', 'execute'), 'service_role can run both functions');
select pg_temp.must(not has_function_privilege('authenticated', 'public.link_statement_evidence(text, uuid, uuid, jsonb, uuid)', 'execute') and not has_function_privilege('anon', 'public.link_statement_evidence(text, uuid, uuid, jsonb, uuid)', 'execute')
  and not has_function_privilege('authenticated', 'public.unlink_statement_evidence(text, uuid, text, uuid)', 'execute') and not has_function_privilege('anon', 'public.unlink_statement_evidence(text, uuid, text, uuid)', 'execute'), 'no client role can run either function');
select pg_temp.must((select count(*) from pg_proc where oid in ('public.link_statement_evidence(text, uuid, uuid, jsonb, uuid)'::regprocedure, 'public.unlink_statement_evidence(text, uuid, text, uuid)'::regprocedure) and prosecdef and exists (select 1 from unnest(proconfig) c where c in ('search_path=""', 'search_path='))) = 2, 'both functions are security definer with an empty search_path');
select pg_temp.must((select allowed_mime_types from storage.buckets where id = 'legal-entity-documents') @> array['message/rfc822','application/pdf','image/jpeg','image/png'] and (select public from storage.buckets where id = 'legal-entity-documents') = false, 'the private vault bucket accepts an original e-mail and stays private');
select pg_temp.must((select pg_get_constraintdef(oid) from pg_constraint where conname = 'entity_finance_events_event_type_check') ilike '%bank_evidence_unlinked%' and (select pg_get_constraintdef(oid) from pg_constraint where conname = 'entity_finance_events_event_type_check') ilike '%bank_evidence_linked%' and (select pg_get_constraintdef(oid) from pg_constraint where conname = 'entity_finance_events_event_type_check') ilike '%asset_unlinked%', 'the audit-event list gained bank_evidence_unlinked and keeps the earlier types');

-- ---------------------------------------------------------------- 2. every refusal (each changes exactly one thing); nothing is linked afterwards
select pg_temp.must(pg_temp.lk('instalment', pg_temp.ins1(pg_temp.i('f1')), '22222222-2222-4222-8222-222222222204', pg_temp.ev(), '00000000-0000-4000-8000-0000000000f1') ilike '%only a Super Admin%', 'an ordinary admin cannot link');
select pg_temp.must(pg_temp.lk('other', pg_temp.ins1(pg_temp.i('f1')), '22222222-2222-4222-8222-222222222204', pg_temp.ev()) ilike '%instalment or for the funding%', 'an unknown kind is refused');
select pg_temp.must(pg_temp.lk('instalment', pg_temp.ins1(pg_temp.i('f1')), '22222222-2222-4222-8222-222222222204', pg_temp.ev('{"holderKind":"personal"}')) ilike '%personal account or card is never attached%', 'a PERSONAL instrument is refused');
select pg_temp.must(pg_temp.lk('instalment', pg_temp.ins1(pg_temp.i('f1')), '22222222-2222-4222-8222-222222222204', pg_temp.ev('{"holderKind":null}')) ilike '%COMPANY instrument%', 'a missing holder kind is refused');
select pg_temp.must(pg_temp.lk('instalment', pg_temp.ins1(pg_temp.i('f1')), '22222222-2222-4222-8222-222222222204', pg_temp.ev('{"instrumentKind":"cheque"}')) ilike '%credit card or a bank account%', 'an unknown instrument kind is refused');
select pg_temp.must(pg_temp.lk('instalment', pg_temp.ins1(pg_temp.i('f1')), '22222222-2222-4222-8222-222222222204', pg_temp.ev('{"accountHolderAsPrinted":"Myredlive Anim Tetey"}')) ilike '%does not match this legal entity%', 'an account holder that is the Founder personally does not match the entity');
select pg_temp.must(pg_temp.lk('instalment', pg_temp.ins1(pg_temp.i('f1')), '22222222-2222-4222-8222-222222222204', pg_temp.ev('{"accountHolderAsPrinted":"FIN ENTITY B W.L.L."}')) ilike '%does not match this legal entity%', 'the other entity''s name does not match');
select pg_temp.must(pg_temp.lk('instalment', pg_temp.ins1(pg_temp.i('f1')), '22222222-2222-4222-8222-222222222204', pg_temp.ev('{"accountHolderAsPrinted":"Fin Entity A (Qatar) WLL"}')) = '', 'baseline: the same holder written differently (case, punctuation, legal form) matches');
select pg_temp.must((select count(*) from public.entity_financing_instalments where bank_evidence_document_id is not null) = 1, 'the baseline link above is in place');
select pg_temp.ul('instalment', pg_temp.ins1(pg_temp.i('f1')), 'Removing the baseline link used only to test holder matching');
select pg_temp.must((select count(*) from public.entity_financing_instalments where bank_evidence_document_id is not null) = 0, 'the baseline link was removed again');
select pg_temp.must(pg_temp.lk('instalment', pg_temp.ins1(pg_temp.i('f1')), '22222222-2222-4222-8222-222222222204', pg_temp.ev('{"instrumentIdentityAsPrinted":"4111 1111 1111 1111"}')) ilike '%full card or account number%', 'an unmasked 16-digit card number is refused');
select pg_temp.must(pg_temp.lk('instalment', pg_temp.ins1(pg_temp.i('f1')), '22222222-2222-4222-8222-222222222204', pg_temp.ev('{"instrumentIdentityAsPrinted":"QA58DOHB00001234567890ABCDEFG"}')) ilike '%full card or account number%', 'an IBAN-shaped value is refused');
select pg_temp.must(pg_temp.lk('instalment', pg_temp.ins1(pg_temp.i('f1')), '22222222-2222-4222-8222-222222222204', pg_temp.ev('{"lineDescriptionAsPrinted":"PAYMENT 5500000000000004"}')) ilike '%full card or account number%', 'a full number inside the description is refused');
select pg_temp.must(pg_temp.lk('instalment', pg_temp.ins1(pg_temp.i('f1')), '22222222-2222-4222-8222-222222222204', pg_temp.ev('{"lineDescriptionAsPrinted":"x"}')) ilike '%line description%', 'a too-short description is refused');
select pg_temp.must(pg_temp.lk('instalment', pg_temp.ins1(pg_temp.i('f1')), '22222222-2222-4222-8222-222222222204', pg_temp.ev('{"basisNote":"short"}')) ilike '%how the statement line was identified%', 'a too-short basis is refused');
select pg_temp.must(pg_temp.lk('instalment', pg_temp.ins1(pg_temp.i('f1')), '22222222-2222-4222-8222-222222222204', pg_temp.ev('{"lineDate":"not-a-date"}')) ilike '%must be valid%', 'an invalid date is refused');
select pg_temp.must(pg_temp.lk('instalment', pg_temp.ins1(pg_temp.i('f1')), '22222222-2222-4222-8222-222222222204', pg_temp.ev(jsonb_build_object('periodTo', (current_date + 5)::text))) ilike '%not in the future%', 'a statement period in the future is refused');
select pg_temp.must(pg_temp.lk('instalment', pg_temp.ins1(pg_temp.i('f1')), '22222222-2222-4222-8222-222222222204', pg_temp.ev(jsonb_build_object('periodFrom', (current_date - 20)::text, 'periodTo', (current_date - 5)::text))) ilike '%outside the statement period%', 'a line outside the statement period is refused');
select pg_temp.must(pg_temp.lk('instalment', pg_temp.ins1(pg_temp.i('f1')), '22222222-2222-4222-8222-222222222201', pg_temp.ev()) ilike '%PDF or image stored as an other financial document%', 'a purchase receipt cannot be the statement');
select pg_temp.must(pg_temp.lk('instalment', pg_temp.ins1(pg_temp.i('f1')), '22222222-2222-4222-8222-222222222206', pg_temp.ev()) ilike '%PDF or image stored as an other financial document%', 'an e-mail (message/rfc822) cannot be the statement');
select pg_temp.must(pg_temp.lk('instalment', pg_temp.ins1(pg_temp.i('f1')), '22222222-2222-4222-8222-222222222203', pg_temp.ev()) ilike '%THIS entity%', 'a statement from ANOTHER entity''s vault is refused');
select pg_temp.must(pg_temp.lk('instalment', pg_temp.ins1(pg_temp.i('f1')), '22222222-2222-4222-8222-222222222204', pg_temp.ev('{"lineCurrency":"USD"}')) ilike '%currency%differs%', 'a different currency is refused');
select pg_temp.must(pg_temp.lk('instalment', pg_temp.ins1(pg_temp.i('f1')), '22222222-2222-4222-8222-222222222204', pg_temp.ev('{"lineAmount":287.24}')) ilike '%amount%differs%', 'a different amount is refused (no variance links)');
select pg_temp.must(pg_temp.lk('instalment', pg_temp.ins1(pg_temp.i('f1')), '22222222-2222-4222-8222-222222222204', pg_temp.ev(jsonb_build_object('lineDate', (current_date - 12)::text))) ilike '%more than 7 days%', 'a line date more than 7 days from the reported payment date is refused');
select pg_temp.must(pg_temp.lk('instalment', pg_temp.ins1(pg_temp.i('f2')), '22222222-2222-4222-8222-222222222204', pg_temp.ev()) ilike '%reported paid%', 'a PENDING instalment cannot be linked');
select pg_temp.must(pg_temp.lk('instalment', '99999999-9999-4999-8999-999999999999', '22222222-2222-4222-8222-222222222204', pg_temp.ev()) ilike '%does not exist%', 'an unknown instalment is refused');
select pg_temp.must((select count(*) from public.entity_financing_instalments where bank_evidence_document_id is not null) = 0 and pg_temp.nev('bank_evidence_linked') = 1, 'after the refusals nothing is linked (only the removed baseline link left its history)');

-- ---------------------------------------------------------------- 3. a valid link: only the link column changes, everything else is exactly as recorded
select pg_temp.must(pg_temp.lk('instalment', pg_temp.ins1(pg_temp.i('f1')), '22222222-2222-4222-8222-222222222204', pg_temp.ev('{"paymentReference":"sp 0001"}')) = '', 'a Super Admin links a company statement to the reported-paid first instalment');
select pg_temp.must((select bank_evidence_document_id from public.entity_financing_instalments where id = pg_temp.ins1(pg_temp.i('f1'))) = '22222222-2222-4222-8222-222222222204', 'the statement is linked to that instalment');
select pg_temp.must((select status = 'paid' and paid_amount = 287.25 and paid_on = current_date - 1 from public.entity_financing_instalments where id = pg_temp.ins1(pg_temp.i('f1'))), 'the instalment keeps its paid status, amount and reported date');
select pg_temp.must((select count(*) from public.entity_financing_instalments i join t_rows r on r.id = i.id where md5((to_jsonb(i) - 'bank_evidence_document_id')::text) <> r.h) = 0, 'every instalment is otherwise byte-identical (only the link column differs)');
select pg_temp.must((select detail ->> 'holderKind' = 'company' and detail ->> 'accountHolderAsPrinted' = 'FIN ENTITY A W.L.L.' and detail ->> 'instrumentIdentityAsPrinted' = 'card ending 4242' and (detail ->> 'lineAmount')::numeric = 287.25 and detail ->> 'currency' = 'QAR'
  and detail ->> 'lineDate' = (current_date - 1)::text and (detail ->> 'dateDifferenceDays')::int = 0 and detail ->> 'referenceMatchesFinancing' = 'true' and detail ->> 'page' = '2' and detail ->> 'statementDocumentId' = '22222222-2222-4222-8222-222222222204'
  from public.entity_finance_events where instalment_id = pg_temp.ins1(pg_temp.i('f1')) and event_type = 'bank_evidence_linked' order by occurred_at desc limit 1), 'the audit event records holder, masked identity, line date, amount, currency, reference match, page and document');
select pg_temp.must(pg_temp.lk('instalment', pg_temp.ins1(pg_temp.i('f1')), '22222222-2222-4222-8222-222222222207', pg_temp.ev()) ilike '%already linked%', 'a second link is refused');
select pg_temp.must(pg_temp.err(format($q$update public.entity_financing_instalments set bank_evidence_document_id = null where id = %L$q$, pg_temp.ins1(pg_temp.i('f1')))) ilike '%already linked%', 'the link cannot be cleared directly');
select pg_temp.must(pg_temp.err(format($q$select set_config('ordift.unlink_evidence', %L, true); update public.entity_financing_instalments set bank_evidence_document_id = null where id = %L$q$, pg_temp.i('f3'), pg_temp.ins1(pg_temp.i('f1')))) ilike '%already linked%', 'the setting must name THIS instalment');
select set_config('ordift.unlink_evidence', '', true);
select pg_temp.must(pg_temp.err(format($q$update public.entity_financing_instalments set bank_evidence_document_id = %L where id = %L$q$, '22222222-2222-4222-8222-222222222207', pg_temp.ins1(pg_temp.i('f1')))) ilike '%already linked%', 'the link cannot be replaced directly');
select pg_temp.must(pg_temp.vd(pg_temp.i('f1')) ilike '%statement is already linked to an instalment%', 'the 0190 void is refused while a statement is linked');

-- ---------------------------------------------------------------- 4. the audited unlink
select pg_temp.must(pg_temp.ul('instalment', pg_temp.ins1(pg_temp.i('f1')), 'short') ilike '%at least 10 characters%', 'unlinking needs a written reason');
select pg_temp.must(pg_temp.ul('instalment', pg_temp.ins1(pg_temp.i('f1')), 'Linked the wrong statement line', '00000000-0000-4000-8000-0000000000f1') ilike '%only a Super Admin%', 'an ordinary admin cannot unlink');
select pg_temp.must(pg_temp.ul('instalment', pg_temp.ins1(pg_temp.i('f3')), 'Nothing is linked to this one') ilike '%no statement is linked%', 'unlinking something that is not linked is refused');
select pg_temp.must(pg_temp.ul('instalment', pg_temp.ins1(pg_temp.i('f1')), 'Linked the wrong statement line') = '', 'a Super Admin unlinks with a written reason');
select pg_temp.must((select bank_evidence_document_id is null and status = 'paid' and paid_amount = 287.25 from public.entity_financing_instalments where id = pg_temp.ins1(pg_temp.i('f1'))), 'after the unlink the payment is again "reported paid" (not verified), facts unchanged');
select pg_temp.must((select detail ->> 'previousStatementDocumentId' = '22222222-2222-4222-8222-222222222204' and detail ->> 'reason' = 'Linked the wrong statement line' from public.entity_finance_events where instalment_id = pg_temp.ins1(pg_temp.i('f1')) and event_type = 'bank_evidence_unlinked' order by occurred_at desc, id desc limit 1), 'the unlink event records the previous statement and the reason');
select pg_temp.must(pg_temp.nev('bank_evidence_linked') = 2 and pg_temp.nev('bank_evidence_unlinked') = 2, 'the earlier link events are retained (append-only): 2 links and 2 unlinks so far (including the baseline pair)');
select pg_temp.must((select count(*) from public.entity_financing_instalments i join t_rows r on r.id = i.id where md5((to_jsonb(i) - 'bank_evidence_document_id')::text) <> r.h) = 0, 'every instalment is still otherwise byte-identical after link and unlink');
select pg_temp.must(pg_temp.lk('instalment', pg_temp.ins1(pg_temp.i('f1')), '22222222-2222-4222-8222-222222222207', pg_temp.ev()) = '', 'after an unlink a corrected link (another statement image) is possible');
select pg_temp.must(pg_temp.ul('instalment', pg_temp.ins1(pg_temp.i('f1')), 'Unlinking so the acquisition can be voided') = '', 'the second statement is unlinked with a reason');
select pg_temp.must(pg_temp.vd(pg_temp.i('f1')) = '', 'after the unlink the 0190 void works again');

-- ---------------------------------------------------------------- 5. funding link (who paid): only a company-account funding source, only a line that matches a reported payment
select pg_temp.must(pg_temp.lk('funding', pg_temp.i('f3'), '22222222-2222-4222-8222-222222222204', pg_temp.ev('{"lineAmount":100}')) ilike '%does not match any reported payment%', 'a funding line that matches no reported payment is refused');
select pg_temp.must(pg_temp.lk('funding', pg_temp.i('f3'), '22222222-2222-4222-8222-222222222204', pg_temp.ev(jsonb_build_object('lineDate', (current_date - 12)::text, 'periodFrom', (current_date - 30)::text))) ilike '%does not match any reported payment%', 'a funding line more than 7 days from the reported date is refused');
select pg_temp.must(pg_temp.lk('funding', pg_temp.i('f3'), '22222222-2222-4222-8222-222222222204', pg_temp.ev('{"accountHolderAsPrinted":"The Founder Personally"}')) ilike '%does not match this legal entity%', 'funding verified by a personal instrument is refused');
select pg_temp.must(pg_temp.lk('funding', pg_temp.i('f3'), '22222222-2222-4222-8222-222222222204', pg_temp.ev()) = '', 'the company-account funding source is linked to a matching company statement line');
select pg_temp.must((select bank_evidence_document_id = '22222222-2222-4222-8222-222222222204' and funding_source_status = 'company_account' and accounting_classification = 'pending_professional_review' from public.entity_equipment_acquisitions where id = pg_temp.i('f3')), 'the acquisition keeps its funding status and classification; only the evidence link is set');
select pg_temp.must(pg_temp.lk('funding', pg_temp.i('f3'), '22222222-2222-4222-8222-222222222207', pg_temp.ev()) ilike '%already linked%', 'a second funding link is refused');
select pg_temp.must(pg_temp.vd(pg_temp.i('f3')) ilike '%statement is already linked to this acquisition%', 'the void is refused while the funding statement is linked');
select pg_temp.must(pg_temp.ul('funding', pg_temp.i('f3'), 'Funding statement linked in error') = '', 'the funding link is unlinked with a reason');
select pg_temp.must((select bank_evidence_document_id is null from public.entity_equipment_acquisitions where id = pg_temp.i('f3')), 'the funding link is removed by the audited unlink');
-- funding source not stated as company
insert into t_ids values ('f4', (select new_acquisition_id from public.record_acquisition_bundle(jsonb_build_object('entityId','11111111-1111-4111-8111-111111111101','acquisition',jsonb_build_object('supplier','Synthetic Supplier','invoiceNumber','STM-4','purchaseDate','2026-11-01','itemDescription','Synthetic bundle item','quantity',1,'currency','QAR','listPrice',800,'discount',0,'net',800,'invoiceDocumentId','22222222-2222-4222-8222-222222222201','fundingStatus','to_confirm'),
  'terms','{"arrangement":"paid_in_full"}'::jsonb,'payment',jsonb_build_object('kind','full','amount',800,'paidOn',(current_date - 1)::text,'method','company_debit_card','evidenceNote','debit card receipt kept by the Founder')), '00000000-0000-4000-8000-0000000000f0')));
select pg_temp.must(pg_temp.lk('funding', pg_temp.i('f4'), '22222222-2222-4222-8222-222222222204', pg_temp.ev('{"lineAmount":800}')) ilike '%only a company-account funding source%', 'a funding source that is not stated as the company account cannot be linked');

-- ---------------------------------------------------------------- 6. nothing else was touched
select pg_temp.must((select exp_n from t_b) = (select count(*) from public.entity_expenses) and (select pay_n from t_b) = (select count(*) from public.payments) and (select apay_n from t_b) + 1 = (select count(*) from public.entity_acquisition_payments), 'no expense and no client payment was created (the one direct payment is the synthetic STM-4 setup)');
select pg_temp.must((select assets_h from t_b) = (select md5(coalesce(string_agg(row_to_json(a)::text, '|' order by a.id), '')) from public.company_assets a) and (select assign_h from t_b) = (select md5(coalesce(string_agg(row_to_json(x)::text, '|' order by x.id), '')) from public.asset_assignments x), 'the asset register and custody are unchanged');
select pg_temp.must((select vault_h from t_b) = (select md5(string_agg(row_to_json(d)::text, '|' order by d.id)) from public.employing_entity_documents d), 'no vault document was changed');
select pg_temp.must((select idx_h from t_b) = (select md5(string_agg(indexdef, '|' order by indexname)) from pg_indexes where tablename in ('entity_equipment_acquisitions','entity_financing_obligations','entity_financing_instalments')), 'the unique indexes are unchanged');
select pg_temp.must((select con_h from t_b) = (select md5(string_agg(conrelid::regclass::text || conname || pg_get_constraintdef(oid), '|' order by conrelid::regclass::text, conname)) from pg_constraint where conrelid in ('public.entity_equipment_acquisitions'::regclass,'public.entity_financing_obligations'::regclass,'public.entity_financing_instalments'::regclass)), 'the acquisition, obligation and instalment constraints are unchanged');
select pg_temp.must((select grants_h from t_b) = (select md5(string_agg(c.relname || a.privilege_type || a.grantee, '|' order by c.relname, a.privilege_type, a.grantee)) from pg_class c join pg_namespace n on n.oid = c.relnamespace, lateral (select (aclexplode(c.relacl)).privilege_type as privilege_type, (aclexplode(c.relacl)).grantee::regrole::text as grantee) a where n.nspname = 'public' and c.relname in ('entity_equipment_acquisitions','entity_financing_obligations','entity_financing_instalments','entity_finance_events')), 'the table grants are unchanged');
select pg_temp.must((select count(*) from public.entity_finance_events where event_type in ('bank_evidence_linked','bank_evidence_unlinked')) = (select count(*) from public.entity_finance_events where detail ? 'kind' and event_type in ('bank_evidence_linked','bank_evidence_unlinked')), 'every statement event carries its kind');
